        +run_id={RUN_ID} \
        eval.deterministic_only=true

    # Full evaluation with LLM judge (uncomment when ready):
    # !python {REPO_DIR}/scripts/run_evaluation.py +run_id={RUN_ID}
else:
    print('No RUN_ID — run training first (Section 6).')

